function conn(){let c=document.querySelector(".connection"),on=navigator.onLine;c.classList.toggle("online",on);c.classList.toggle("offline",!on);$("connectionText").textContent=on?"Conectado":"Modo offline"}
window.addEventListener("online",conn);window.addEventListener("offline",conn);conn();
