(d.rounds||[]).forEach((r,i)=>{ensure(55);if(i%2===0)box(40,y-24,515,27,"0.97 0.98 1");t(45,y-12,7,cp(r.ponto||"").slice(0,32));t(238,y-12,7,r.ocorrencia||"");t(333,y-12,7,r.chegada||"");t(413,y-12,7,r.hodometro||"");t(488,y-12,7,r.saida||"");ln(40,y-25,555,y-25);y-=27});
