(async()=>{try{await openDB();let d=await store("readonly","get");if(d)restore(d);else addRound();status("Dados armazenados neste aparelho.")}catch(e){addRound();status("Armazenamento local indisponível neste navegador.")}if("serviceWorker"in navigator&&location.protocol!=="file:")navigator.serviceWorker.register("./sw.js").catch(()=>{})})();
